#include &lt;stdio.h&gt; int main(void) {
printf(“Welcome to C! \n”);
}
#include viene eseguito nel pre-processore, prima del compilatore
int main(void) è la firma standard della funzione principale del programma
\n serve ad andare a capo
%d segnaposto per un intero
&amp;variabile indirizzo della variabile
\scanf(“%d”, &amp;variabile) serve a a scrivere nell’indirizzo della variabile un intero
